package com.enterpriseflow.entity;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="notifications") public class Notification {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="recipient_id",nullable=false) private User recipient; private String title; @Column(columnDefinition="TEXT") private String body; private String type; private boolean read; private Instant createdAt; protected Notification(){} public Notification(User u,String t,String b,String type){recipient=u;title=t;body=b;this.type=type;} @PrePersist void on(){createdAt=Instant.now();} public UUID getId(){return id;}public User getRecipient(){return recipient;}public String getTitle(){return title;}public String getBody(){return body;}public String getType(){return type;}public boolean isRead(){return read;}public Instant getCreatedAt(){return createdAt;}public void markRead(){read=true;}}
